#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int id;
    int is_start;
    int timestamp;
} Event;

int* exclusiveTime(int n, Event* events, int m, int* returnSize) {
    int* result = (int*)calloc((size_t)n, sizeof(int));
    int* stack = (int*)malloc((size_t)m * sizeof(int));
    int top = -1;
    int prev = 0;

    for (int i = 0; i < m; ++i) {
        Event e = events[i];
        if (e.is_start) {
            if (top >= 0) result[stack[top]] += e.timestamp - prev;
            stack[++top] = e.id;
            prev = e.timestamp;
        } else {
            result[stack[top--]] += e.timestamp - prev + 1;
            prev = e.timestamp + 1;
        }
    }

    free(stack);
    *returnSize = n;
    return result;
}

