class Solution {
public:
    vector<int> exclusiveTime(int n, const vector<string>& logs) {
        vector<int> result(n, 0);
        vector<int> st;
        int prev = 0;

        for (const string& log : logs) {
            size_t p1 = log.find(':');
            size_t p2 = log.find(':', p1 + 1);
            int id = stoi(log.substr(0, p1));
            string event = log.substr(p1 + 1, p2 - p1 - 1);
            int ts = stoi(log.substr(p2 + 1));

            if (event == "start") {
                if (!st.empty()) result[st.back()] += ts - prev;
                st.push_back(id);
                prev = ts;
            } else {
                result[st.back()] += ts - prev + 1;
                st.pop_back();
                prev = ts + 1;
            }
        }
        return result;
    }
};

