int main(void) {
    char line[2000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    char *p = line;
    while (*p == ' ' || *p == '[') ++p;
    int n = atoi(p);

    Event* events = (Event*)malloc(500 * sizeof(Event));
    int m = 0;

    p = strchr(line, ',');
    if (!p) return 1;

    while ((p = strchr(p, '"')) != NULL) {
        ++p;
        if (!isdigit((unsigned char)*p)) continue;

        char *end = NULL;
        int id = (int)strtol(p, &end, 10);
        if (!end || *end != ':') continue;
        p = end + 1;

        int is_start = 0;
        if (strncmp(p, "start:", 6) == 0) {
            is_start = 1;
            p += 6;
        } else if (strncmp(p, "end:", 4) == 0) {
            is_start = 0;
            p += 4;
        } else continue;

        int ts = (int)strtol(p, &end, 10);
        if (!end || *end != '"') continue;

        events[m++] = (Event){id, is_start, ts};
        p = end + 1;
    }

    int returnSize = 0;
    int* result = exclusiveTime(n, events, m, &returnSize);

    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        if (i) printf(",");
        printf("%d", result[i]);
    }
    printf("]\n");

    free(result);
    free(events);
    return 0;
}

