public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();

        Matcher nMatcher = Pattern.compile("^\\s*\\[\\s*(\\d+)\\s*,").matcher(line);
        if (!nMatcher.find()) throw new IllegalArgumentException("Invalid input");
        int n = Integer.parseInt(nMatcher.group(1));

        Matcher logMatcher = Pattern.compile("\"([^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"").matcher(line);
        List<String> logs = new ArrayList<>();
        while (logMatcher.find()) {
            String value = logMatcher.group(1);
            if (value.matches("\\d+:(?:start|end):\\d+")) {
                logs.add(value);
            }
        }

        int[] result = new Solution().exclusiveTime(n, logs);
        System.out.print("[");
        for (int i = 0; i < result.length; i++) {
            if (i > 0) System.out.print(",");
            System.out.print(result[i]);
        }
        System.out.println("]");
    }
}

